#!/usr/bin/env node
/**
 * Coverage Tier Validation Script
 *
 * Reads coverage/coverage-summary.json (generated by vitest --coverage)
 * and validates per-tier coverage targets defined in
 * openspec/specs/wedding-trend/spec.md §7.1.
 *
 * Usage:
 *   node scripts/gates/check-coverage-tiers.mjs           # check generated report
 *   COVERAGE_JSON=path node scripts/gates/check-coverage-tiers.mjs  # custom path
 *
 * Exit codes:
 *   0 - All tiers pass
 *   1 - Some tiers below target
 *   2 - Coverage report not found
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "../..");

// ── Tier configuration (mirrors spec.md §7.1) ──────────────────────────
// 対象ファイルは実際の src/ ツリーに合わせて調整済み。
const TIERS = [
  {
    name: "Tier 1: 純粋ロジック",
    target: 95,
    metric: "statements",
    patterns: [
      /\/lib\/url\.ts$/,
      /\/lib\/llm\/signature\.ts$/,
      /\/lib\/llm\/schemas\.ts$/,
      /\/lib\/constants\.ts$/,
      /\/lib\/scoring\/usefulness\.ts$/,
    ],
  },
  {
    name: "Tier 2: パース・判定",
    target: 85,
    metric: "statements",
    patterns: [/\/lib\/sources\/base\/feed-parser\.ts$/, /\/lib\/embed\/providers\.ts$/],
  },
  {
    name: "Tier 3: 収集アダプタ",
    target: 80,
    metric: "statements",
    patterns: [
      /\/lib\/sources\/(hatena-bookmark|google-news|note|ameblo)\.ts$/,
      /\/lib\/sources\/base\/rss-fetcher\.ts$/,
      /\/lib\/embed\/oembed\.ts$/,
    ],
  },
  {
    name: "Tier 4: LLM 制御",
    target: 80,
    metric: "statements",
    patterns: [/\/lib\/llm\/batch\.ts$/, /\/lib\/llm\/client\.ts$/],
  },
  {
    name: "Tier 5: API ルート",
    target: 70,
    metric: "statements",
    patterns: [
      /\/app\/api\/ingest\/route\.ts$/,
      /\/app\/api\/submit-url\/route\.ts$/,
      // ルートハンドラから切り出した本体。以前はルート側で計測されていた。
      /\/lib\/pipeline\/ingest\.ts$/,
      /\/lib\/pipeline\/submit-url\.ts$/,
    ],
  },
  {
    name: "Tier 6: データアクセス",
    target: 65,
    metric: "statements",
    patterns: [
      /\/lib\/db\/repository\.ts$/,
      /\/lib\/db\/query\.ts$/,
      /\/lib\/db\/feed\.ts$/,
      /\/lib\/db\/ingest\.ts$/,
      /\/lib\/db\/publication\.ts$/,
      /\/lib\/db\/discovery\.ts$/,
      /\/lib\/db\/gate-state\.ts$/,
    ],
  },
  {
    name: "Tier 7: RSC / UI",
    target: null, // Excluded from unit test coverage (verified via smoke test)
    metric: "statements",
    patterns: [/\/app\/page\.tsx$/, /\/app\/layout\.tsx$/, /\/components\/.+\.tsx$/],
  },
];

// ── Helpers ────────────────────────────────────────────────────────────

function loadCoverage(path) {
  if (!existsSync(path)) {
    console.error(`[coverage-check] Coverage report not found: ${path}`);
    console.error(`[coverage-check] Run 'pnpm exec vitest run --coverage' first.`);
    process.exit(2);
  }
  return JSON.parse(readFileSync(path, "utf-8"));
}

function metricKey(metric) {
  return metric === "statements" ? "statements" : metric;
}

/** Compute aggregate coverage for a set of files (optionally excluding some). */
function aggregateCoverage(report, files, metric) {
  if (files.length === 0) return null;

  let totalCovered = 0;
  let total = 0;

  for (const file of files) {
    const data = report[file];
    if (!data) continue;
    const key = metricKey(metric);
    totalCovered += data[key]?.covered ?? 0;
    total += data[key]?.total ?? 0;
  }

  if (total === 0) return null;
  return { pct: (totalCovered / total) * 100, covered: totalCovered, total };
}

function formatPct(value) {
  return `${value.toFixed(2)}%`;
}

// ── Main ───────────────────────────────────────────────────────────────

function main() {
  const jsonPath = process.env.COVERAGE_JSON || resolve(ROOT, "coverage/coverage-summary.json");

  const report = loadCoverage(jsonPath);

  /** All source file paths from the report. */
  const allFiles = Object.keys(report).filter((f) => f.includes("/src/"));

  let allPass = true;
  const results = [];

  for (const tier of TIERS) {
    const matchedFiles = allFiles.filter((f) => tier.patterns.some((p) => p.test(f)));

    if (matchedFiles.length === 0) {
      results.push({ tier: tier.name, status: "⚠️  No files matched" });
      continue;
    }

    if (tier.target === null) {
      const agg = aggregateCoverage(report, matchedFiles, tier.metric);
      const pctStr = agg ? formatPct(agg.pct) : "N/A";
      results.push({
        tier: tier.name,
        stmts: pctStr,
        status: `ℹ️  (${matchedFiles.length} files, excluded — smoke test で担保)`,
        pass: true,
      });
      continue;
    }

    const agg = aggregateCoverage(report, matchedFiles, tier.metric);
    if (!agg) {
      results.push({
        tier: tier.name,
        stmts: "N/A",
        status: "⚠️  No coverage data",
      });
      continue;
    }

    const primaryPct = agg.pct;
    let pass = primaryPct >= tier.target;
    if (!pass) allPass = false;

    const detail = `(${agg.covered}/${agg.total} ${tier.metric})`;

    results.push({
      tier: tier.name,
      stmts: formatPct(primaryPct),
      target: `${tier.target}%`,
      status: pass ? "✅ PASS" : "❌ FAIL",
      pass,
      detail,
    });
  }

  // ── Output ────────────────────────────────────────────────────────────
  console.log("");
  console.log("📊 Coverage Tier Validation");
  console.log("=".repeat(60));

  for (const r of results) {
    const line = [
      r.tier.padEnd(35),
      (r.stmts || "").padStart(8),
      r.target ? `  target: ${r.target}`.padEnd(12) : " ".padEnd(12),
      r.status || "",
      r.detail || "",
    ].join("");
    console.log(line);
  }

  console.log("=".repeat(60));

  if (allPass) {
    console.log("✅ All tiers meet coverage targets.\n");
    process.exit(0);
  } else {
    console.log("❌ Some tiers are below coverage targets.\n");
    process.exit(1);
  }
}

main();
